    /**
     * Gives the claim being opened its number: while the sheet's period numbering from is set and its today is on or
     * after it, the next in the sequence of the period the claim's due-by falls in (X for none), else the sheet's next.
     * The sheet is locked, so two claims opened at once never get the same one.
     */
    private void number(String sheetId, Claim claim) {
        if (!numbersByPeriod(sheetId)) {
            claim.setNumber(String.valueOf(sheets.nextClaimNumber(sheetId)));
            return;
        }
        String sequence = sequenceOn(sheetId, claim.getDueBy());
        Long last = claims.lastInSequence(sheetId, sequence);
        claim.numberIn(sequence, last == null ? 1 : last + 1);
    }

    /**
     * Takes in a claim moved to the sheet from another: one that had a number there gets the sheet's next, as one
     * being opened would, and its tags are kept as used on the sheet.
     */
    @Transactional
    public void takeIn(String sheetId, Claim claim) {
        if (claim.getNumber() != null) {
            claim.clearNumber();
            number(sheetId, claim);
        }
        keepTags(sheetId, claim.getTags());
    }

    /** Gives a claim copied onto the sheet from another, where it had a number, the sheet's next. */
    @Transactional
    public void numberCopy(String sheetId, Claim claim) {
        claim.clearNumber();
        number(sheetId, claim);
    }

    /**
     * Gives a numbered claim the next number in the sequence it would be numbered in now; its old one is retired, so it
     * is never given again (a sheet number never is: the sheet's count only rises).
     */
    private void renumber(String sheetId, Claim claim) {
        if (claim.getNumberSequence() != null) {
            claims.retireNumber(sheetId, claim.getNumberSequence(), claim.getNumberInSequence());
        }
        claim.clearNumber();
        number(sheetId, claim);
    }

    /** Whether the sheet numbers claims by period: its period numbering from is set and its today on or after it. */
    private boolean numbersByPeriod(String sheetId) {
        Sheet sheet = sheets.load(sheetId);
        LocalDate from = sheet.getPeriodNumberingFrom();
        return from != null && !sheet.getToday().isBefore(from);
    }

    /** The number sequence of a claim due by the date: the name of the period it is in, or X for none. */
    private String sequenceOn(String sheetId, LocalDate date) {
        return periods.findFirstBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId, date, date)
                .map(Period::getName).orElse(NO_PERIOD);
    }

    /**
     * The claim's rate figure: at the rate its person's grade in force on its date has in force on that date, rounded
     * as the sheet's policy date decides for it, with no floor; null (n/a) with none.
     */
    public BigDecimal rateFigure(String sheetId, Person person, Claim claim) {
        Sheet sheet = sheets.load(sheetId);
        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
                .map(pct -> dueOn(claim.getAmount(), pct, rounding)).orElse(null);
    }

    /** What a candidate rate for a grade would change: how many claims would show a different due, and by how much. */
    public record RatePreview(int count, BigDecimal diff) {
    }

    /**
     * Previews the grade's rate at the percent on every date, saving nothing: the OPEN and PENDING claims whose
     * person has the grade in force on the claim's date and whose due would differ, and the sum of new due minus
     * current due (an n/a due counts as 0.00). A claim bound by a statement does not change.
     */
    @Transactional(readOnly = true)
    public RatePreview previewRate(String sheetId, String grade, BigDecimal pct) {
        Sheet sheet = sheets.load(sheetId);
        return sheets.findById(id).orElseGet(() -> create(id));
    }

    /**
     * Change the sheet's today; every date decision on the sheet follows it. It has no audit line of its own, only
     * the figures it moves, after a SNAPSHOT line per person with their due-total on the day being left. What follows
     * a today change (the periods it closes) runs before those are rolled up.
     */
    @Transactional
    public Sheet setToday(String by, String id, LocalDate today) {
        Sheet sheet = load(id);
        RollupService.Snapshot before = rollup.snapshot(id);
        rollup.recordSnapshot(by, id, before);
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        events.publishEvent(new TodayChanged(by, saved));
        rollup.recordChanges(by, id, before);
        return saved;
    }

    /** Loads the sheet and locks it until the transaction ends, so changes checked against the whole sheet run in turn. */
    @Transactional
    public Sheet lock(String id) {
        load(id);
        return sheets.findWithLockById(id).orElseThrow();
    }

    /**
     * Takes the sheet's next claim number: the one after the last given on any sheet of its tree, which share one
     * number sequence. The tree's root is locked, so two callers on the tree at once never get the same one.
     */
    @Transactional
    public long nextClaimNumber(String id) {
        load(id);
        Set<String> tree = tree(id);
        sheets.findWithLockById(root(id)).orElseThrow();
        long next = sheets.lastClaimNumberOf(tree) + 1;
        sheets.setClaimNumber(id, next);
        return next;
    }

    /** The top of the sheet's tree: its parent, their parent and so on, as far as the sheets exist. */
    private String root(String id) {
        Set<String> seen = new HashSet<>();
        String at = id;
        while (seen.add(at)) {
            String parent = sheets.findById(at).map(Sheet::getParentId).orElse(null);
            if (parent == null || !sheets.existsById(parent)) {
                break;
            }
            at = parent;
        }
        return at;
    }

    /** Every sheet of the sheet's tree, the sheet itself among them: its root and all the sheets below it. */
    private Set<String> tree(String id) {
        String root = root(id);
        Set<String> tree = new LinkedHashSet<>(List.of(root));
        ArrayDeque<String> toVisit = new ArrayDeque<>(List.of(root));
        while (!toVisit.isEmpty()) {
            for (Sheet child : sheets.findByParentIdOrderByIdAsc(toVisit.poll())) {
                if (tree.add(child.getId())) {
                    toVisit.add(child.getId());
                }
            }
        }
        tree.add(id);
        return tree;
    }

    /** Takes the sheet's next settle batch number; two callers at once never get the same one. */
    @Transactional
    public int nextSettleBatch(String id) {
        load(id);
        sheets.incrementSettleBatch(id);
        return sheets.lastSettleBatch(id);
    }

    private Sheet create(String id) {
        try {
            return sheets.saveAndFlush(new Sheet(id));
        } catch (DataIntegrityViolationException e) {
            // another user created it at the same moment
            return sheets.findById(id).orElseThrow(() -> e);
        }
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.LockModeType;
import java.util.Collection;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface SheetRepository extends JpaRepository<Sheet, String> {

    /** The sheet's children: the sheets naming it as their parent. */
    List<Sheet> findByParentIdOrderByIdAsc(String parentId);

    /** The sheet, locked until the transaction ends. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    Optional<Sheet> findWithLockById(String id);

    /** The last claim number given on any of the sheets; 0 for none. */
    @Query(value = "SELECT COALESCE(MAX(last_claim_number), 0) FROM sheet WHERE id IN (:ids)", nativeQuery = true)
    long lastClaimNumberOf(@Param("ids") Collection<String> ids);

    /** Sets the sheet's last claim number. */
    @Modifying(flushAutomatically = true)
    @Query(value = "UPDATE sheet SET last_claim_number = :number WHERE id = :id", nativeQuery = true)
    int setClaimNumber(@Param("id") String id, @Param("number") long number);

    /** Moves the sheet's last settle batch number on by one; the row stays locked until the transaction ends. */
    @Modifying(flushAutomatically = true)
    @Query(value = "UPDATE sheet SET last_settle_batch = last_settle_batch + 1 WHERE id = :id", nativeQuery = true)
    int incrementSettleBatch(@Param("id") String id);

    @Query(value = "SELECT last_settle_batch FROM sheet WHERE id = :id", nativeQuery = true)
    int lastSettleBatch(@Param("id") String id);
}
